c = 3   # Number of boxes

# Create a matrix of decision variables: M[i][j] is True if ball i is in box j
M = boolvar(shape=(n, c), name="M")

model = Model()

# Each ball must be in exactly one box
for i in range(n):
    model += sum(M[i]) == 1

# For each x + y = z, not all three in the same box
